[
  {
    "enable": true,
    "asset": "Plant",
    "condition": "PLC_Test.RunningA == 1",
    "message": "Device started A",
    "actions": ""
  },
  {
    "enable": true,
    "asset": "Plant",
    "condition": "PLC_Test.RunningB == 1",
    "message": "Device started B",
    "actions": ""
  }
]

[
  {
    "name": "TempConverterA",
    "readConversion": "value * 1.8 + 32",
    "writeConversion": "(value - 32) / 1.8",
    "description": "Celsius to Fahrenheit A"
  },
  {
    "name": "TempConverterB",
    "readConversion": "value * 2",
    "writeConversion": "value / 2",
    "description": "Scale by two B"
  }
]

[
  {
    "id": 1,
    "enable": true,
    "name": "Anonymous",
    "username": "",
    "description": "Reserved user for clients that connect without credentials.",
    "acls": [
      {
        "topicFilter": "public/#",
        "access": "Subscribe"
      }
    ]
  }
]

[
  {
    "enable": true,
    "name": "MqttDevice1A",
    "template": "",
    "timeout": 5000,
    "description": "MQTT Device A"
  },
  {
    "enable": true,
    "name": "MqttDevice1B",
    "template": "",
    "timeout": 5000,
    "description": "MQTT Device B"
  }
]

[
  {
    "name": "VfdPump",
    "description": "Pump variant with a VFD - derives every Pump member and adds its own",
    "baseDefinition": "Pump",
    "slots": [],
    "parameters": [
      {
        "name": "HighSpeedLimit",
        "label": "High speed alarm limit",
        "type": "Number",
        "defaultValue": "3600"
      }
    ],
    "variableMembers": [
      {
        "enable": true,
        "name": "{Plc}.{Instance}_VfdFrequency",
        "deviceName": "{Plc}",
        "units": "Hz",
        "minRaw": 0,
        "maxRaw": 60,
        "minScaled": 0,
        "maxScaled": 60,
        "historian": true,
        "modbusTcpType": "REAL",
        "modbusTcpAddress": "%MW{= {BaseAddr} + 10 }"
      }
    ],
    "alarmMembers": [],
    "eventMembers": [],
    "scriptMembers": []
  },
  {
    "name": "DosingSkid",
    "description": "Skid containing two identical motors - {Slot} keeps the copies distinct",
    "baseDefinition": "",
    "slots": [
      {
        "name": "MotorA",
        "definition": "Motor",
        "parameterMapping": {
          "BaseAddr": "{= {SkidBase} + 0 }",
          "Drive": "{Plc}"
        },
        "includeWhen": ""
      },
      {
        "name": "MotorB",
        "definition": "Motor",
        "parameterMapping": {
          "BaseAddr": "{= {SkidBase} + 100 }",
          "Drive": "{Plc}"
        },
        "includeWhen": "{HasSecondMotor}"
      }
    ],
    "parameters": [
      {
        "name": "SkidBase",
        "label": "Skid base address",
        "type": "Number",
        "defaultValue": "1000"
      },
      {
        "name": "HasSecondMotor",
        "label": "Second motor fitted",
        "type": "Text",
        "defaultValue": "true"
      },
      {
        "name": "Plc",
        "label": "Controller",
        "type": "Device",
        "defaultValue": ""
      }
    ],
    "variableMembers": [],
    "alarmMembers": [],
    "eventMembers": [],
    "scriptMembers": []
  }
]

{
  "ids": [
    1
  ],
  "reason": "Adopt existing hand-written rows into the type",
  "adopt": true
}
